{"op":"add","path":"/elements/cards","value":{"type":"Grid","props":{"columns":"3","gap":"md"},"repeat":{"statePath":"/laptops","key":"id"},"children":["card"]}}
{"op":"add","path":"/elements/card","value":{"type":"Card","props":{"title":{"$item":"name"},"description":{"$item":"tagline"}},"children":["card-price","card-rating","card-best","card-pros","card-cons"]}}
