{"op":"add","path":"/elements/pick-forge","value":{"type":"Alert","props":{"title":"Pick: Forge 16","description":"16-core CPU, 32 GB RAM, 1 TB SSD and full ports for video editing, 3D and gaming. Expect 2.1 kg and 9 h battery."},"visible":{"$state":"/pick","eq":"Maximum performance"},"children":[]}}
